-- IDPMS ORM 송신 : 수입 당발송금 ORM(Outward Remittance Message) 송신 스테이징.
CREATE TABLE TB_IF_IDPMS_ORM (
  ORM_NO                   VARCHAR2(20) NOT NULL,
