  APPR_USER_ID             VARCHAR2(10),
  CONSTRAINT PK_CIMS_RETURN PRIMARY KEY (RETURN_ID)
);
COMMENT ON TABLE TB_CIMS_RETURN IS 'CIMS 보고 헤더';
COMMENT ON COLUMN TB_CIMS_RETURN.RETURN_ID IS '회차ID';
COMMENT ON COLUMN TB_CIMS_RETURN.RETURN_CODE IS '리턴코드 - LRS_DAILY/R_RETURN/SRVA/ODI 등(RBI 리턴명세 기준)';
